1	// FlashAttention-2-style BF16 forward kernel for sm_86 (RTX 3090 Ti).
2	// - wmma 16x16x16 tensor-core matmuls (mma.sync.m16n8k16 under the hood)
3	// - cp.async single-buffered K/V tiles (39,936 B smem -> 2 blocks/SM on sm_86,
4	//   which doubles warps-in-flight vs a 96 KB double-buffered layout);
5	//   padded row stride (136 bf16) makes ldmatrix reads conflict-free
6	// - online softmax; softmaxed scores are staged as bf16 through a small
7	//   per-warp shared tile (true row/col layout) before the PV matmul, because
8	//   the m16n16k16 accumulator layout differs from the matrix_a layout.
9	#include <torch/extension.h>
10	#include <ATen/cuda/CUDAContext.h>
11	#include <c10/cuda/CUDAGuard.h>
12	#include <cuda_bf16.h>
13	#include <mma.h>
14	#include <math.h>
15	
