18	using namespace nvcuda;
19	
20	constexpr int BLOCK_M = 64;    // query rows per block
21	constexpr int BLOCK_N = 16;    // kv rows per tile
22	constexpr int HEAD_DIM = 128;
23	constexpr int NUM_WARPS = 4;
24	constexpr int NUM_THREADS = NUM_WARPS * 32;
25	constexpr int PADDED_D = HEAD_DIM + 8;        // 16 B/row padding
26	constexpr int P_COLS = BLOCK_N + 8;           // P tile cols (24) -> conflict-free bf16 smem writes
27	constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;  // per K or V tile (bf16)
28	constexpr int O_ELEMS = BLOCK_M * PADDED_D;     // O staging (reuses Q buffer)
29	constexpr int P_SMEM = NUM_WARPS * 16 * P_COLS * 2;  // bf16 P staging for PV (3,072 B)
30	// Single-buffered K/V (2 tiles) keeps smem at 29,184 B -> 3 blocks/SM on sm_86
31	// (12 warps vs 8), trading tile width for occupancy on this latency-bound kernel.
32	constexpr int SMEM_BYTES = 2 * TILE_ELEMS * 2 + O_ELEMS * 2 + P_SMEM;  // 29,184 B
