34	__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
35	    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
36	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
37	}
38	__device__ __forceinline__ void cp_async_commit() {
39	    asm volatile("cp.async.commit_group;\n");
40	}
41	template<int N>
42	__device__ __forceinline__ void cp_async_wait() {
43	    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
44	}
