46	// Copy an nrows x HEAD_DIM tile from gmem (rows row0..) to padded shared,
47	// zero-filling rows past seq_len. Used for K/V tiles (nrows = BLOCK_N) and
48	// to stage Q (nrows = BLOCK_M).
49	__device__ __forceinline__ void load_tile(
50	    const __nv_bfloat16* __restrict__ src, __nv_bfloat16* __restrict__ dst,
51	    int row0, int seq_len, int nrows)
52	{
53	    const int CHUNKS = nrows * HEAD_DIM / 8;  // 16B chunks
54	#pragma unroll
55	    for (int i = threadIdx.x; i < CHUNKS; i += NUM_THREADS) {
56	        const int row = i / (HEAD_DIM / 8);
57	        const int col8 = i % (HEAD_DIM / 8);
58	        const int grow = row0 + row;
59	        __nv_bfloat16* s = dst + row * PADDED_D + col8 * 8;
60	        if (grow < seq_len) {
61	            cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
62	        } else {
63	            *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
64	        }
65	    }
66	}
