68	__device__ __forceinline__ float warp_max4(float v) {
69	#pragma unroll
70	    for (int off = 1; off < 4; off <<= 1)
71	        v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off));
72	    return v;
73	}
74	__device__ __forceinline__ float warp_sum4(float v) {
75	#pragma unroll
76	    for (int off = 1; off < 4; off <<= 1)
77	        v += __shfl_xor_sync(0xffffffffu, v, off);
78	    return v;
79	}
